function safeParse(key){try{return JSON.parse(localStorage.getItem(key)||'[]');}catch(e){return [];}}
let state = { filter: 'all', audience: 'all', query: '', sort: 'featured', color: new Set(), price: new Set(), cart: safeParse('gioventrueCartV2'), favorites: new Set(safeParse('gioventrueFavorites')) };
const $ = (s, r=document)=>r.querySelector(s); const $$ = (s,r=document)=>[...r.querySelectorAll(s)];
const money = v => new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(v);
function saveCart(){localStorage.setItem('gioventrueCartV2', JSON.stringify(state.cart));}
function saveFavorites(){localStorage.setItem('gioventrueFavorites', JSON.stringify([...state.favorites]));}
function toggleFavorite(sku){state.favorites.has(sku)?state.favorites.delete(sku):state.favorites.add(sku); saveFavorites(); $$(`[data-favorite="${sku}"]`).forEach(b=>{b.classList.toggle('active',state.favorites.has(sku)); b.textContent=state.favorites.has(sku)?'Favoritos ♥':'Favoritos ♡';});}
function img(src, alt=''){return `<img src="${src}" alt="${alt}" loading="lazy">`;}
function productCard(p){return `<article class="product"><a href="#/producto/${p.sku}" class="product-img">${img(p.images[0],p.name)}<button class="quick" type="button" data-add="${p.sku}" aria-label="Agregar ${p.name}">+</button></a><div class="tag">${p.isNew?'Lo nuevo':p.isBestSeller?'Lo más vendido':'Disponible'}</div><h3><a href="#/producto/${p.sku}">${p.name}</a></h3><p>${p.categoryLabel}${p.category.endsWith('-dama')?' '+p.audience:''}${p.color?' · '+p.color:''}</p><p>SKU ${p.sku}</p><p class="price">${money(p.price)}</p></article>`;}
function getFiltered(){let arr=[...PRODUCTS]; if(state.filter!=='all') arr=arr.filter(p=>p.category===state.filter); if(state.audience && state.audience!=='all') arr=arr.filter(p=>p.audience===state.audience); if(state.query){let q=state.query.toLowerCase(); arr=arr.filter(p=>[p.name,p.sku,p.categoryLabel,p.color,p.material].join(' ').toLowerCase().includes(q));} if(state.color.size) arr=arr.filter(p=>state.color.has(p.color)); if(state.price.size) arr=arr.filter(p=>{ for(const band of state.price){ if(band==='lt250' && p.price<250) return true; if(band==='250-349' && p.price>=250 && p.price<=349) return true; if(band==='gte350' && p.price>=350) return true; } return false; }); if(state.sort==='priceAsc') arr.sort((a,b)=>a.price-b.price); if(state.sort==='priceDesc') arr.sort((a,b)=>b.price-a.price); if(state.sort==='name') arr.sort((a,b)=>a.name.localeCompare(b.name)); if(state.sort==='new') arr.sort((a,b)=>(b.isNew?1:0)-(a.isNew?1:0)); return arr;}
function renderHome(){const heroImgs=[PRODUCTS[0].images[0],PRODUCTS[5].images[0],PRODUCTS[8].images[0]]; $('#app').innerHTML=`<section class="notice"><p><strong>Compra por WhatsApp</strong><span>Agrega a la bolsa y manda tu pedido con cantidades y subtotal.</span></p></section><section class="hero"><div class="hero-art"><div class="hero-copy"><p class="eyebrow">Nueva temporada</p><h1>Accesorios con actitud</h1><p>Mochilas, baberos, diademas y sets listos para vender por pieza o mayoreo.</p><div class="hero-actions"><a class="primary" href="#/productos">Comprar ahora</a><a class="secondary" href="#/productos?best=true">Ver best sellers</a></div></div><div class="hero-photos">${heroImgs.map((x)=>img(x, 'Producto Gioventrue')).join('')}</div></div></section><section class="section"><div class="section-title"><h2>Lo nuevo</h2><a class="textlink" href="#/productos">Ver todo</a></div><div class="rail">${PRODUCTS.filter(p=>p.isNew).slice(0,6).map(p=>`<article class="feature"><a href="#/producto/${p.sku}">${img(p.images[0],p.name)}</a><h3>${p.name}</h3><p>${p.shortDescription}</p><a class="textlink" href="#/producto/${p.sku}">Comprar</a></article>`).join('')}</div></section><section class="section"><div class="section-title"><h2>Compra por categorías</h2></div><div class="category-grid"><button class="cat-card" data-cat="mochilas">${img(PRODUCTS[0].images[0],'Mochilas')}<span>Mochilas</span></button><button class="cat-card" data-cat="baberos">${img(PRODUCTS[5].images[0],'Baberos')}<span>Baberos</span></button><button class="cat-card" data-cat="diademas">${img(PRODUCTS[8].images[0],'Diademas')}<span>Diademas</span></button><button class="cat-card" data-audience="Dama">${img((PRODUCTS.find(p=>p.audience==='Dama')||PRODUCTS[0]).images[0],'Dama')}<span>Dama</span></button></div></section><section class="section"><div class="section-title"><h2>Best Sellers</h2><a class="textlink" href="#/productos?best=true">Ver todo</a></div><div class="rail">${PRODUCTS.filter(p=>p.isBestSeller).map(productCard).join('')}</div></section>`; bindDynamic();}
function renderProducts(params={}){const prevAudience=state.audience; const catAudience=(params.cat&&params.cat!=='all')?PRODUCTS.find(p=>p.category===params.cat)?.audience:null; state.audience=params.audience||catAudience||state.audience||'all'; state.filter=params.cat||((params.audience&&params.audience!==prevAudience)?'all':(state.filter||'all')); state.query=params.q||state.query||''; const best=params.best==='true'; let arr=getFiltered(); if(best) arr=arr.filter(p=>p.isBestSeller); const audPool=state.audience!=='all'?PRODUCTS.filter(p=>p.audience===state.audience):PRODUCTS; const cats=[...new Set(audPool.map(p=>p.category))]; const catLabel=c=>{const l=PRODUCTS.find(p=>p.category===c)?.categoryLabel; return cats.filter(c2=>PRODUCTS.find(p=>p.category===c2)?.categoryLabel===l).length>1?`${l} (${PRODUCTS.find(p=>p.category===c)?.audience})`:l;}; const colors=[...new Set(PRODUCTS.map(p=>p.color).filter(Boolean))]; $('#app').innerHTML=`<section class="shop"><div class="breadcrumbs"><a href="#/">Inicio</a> / Productos</div><div class="shop-head"><div><h1>${state.filter!=='all'?(PRODUCTS.find(p=>p.category===state.filter)?.categoryLabel||'Productos'):(state.audience!=='all'?state.audience:'Todos los productos')} (${arr.length})</h1></div><div class="shop-tools"><button class="tool-btn" id="toggleFilters">Ocultar filtros ⚙</button><label>Ordenar por <select class="sort" id="sortSelect"><option value="featured">Destacados</option><option value="new">Nuevo</option><option value="priceAsc">Menor precio</option><option value="priceDesc">Mayor precio</option><option value="name">Nombre</option></select></label></div></div><div class="shop-layout"><aside class="sidebar" id="sidebar"><div class="side-group"><h3>Categoría</h3>${cats.map(c=>`<label class="check"><input type="radio" name="cat" value="${c}" ${state.filter===c?'checked':''}> ${catLabel(c)}</label>`).join('')}<label class="check"><input type="radio" name="cat" value="all" ${state.filter==='all'?'checked':''}> Todo</label></div><div class="side-group"><h3>Color</h3>${colors.map(c=>`<label class="check"><input type="checkbox" data-color="${c}" ${state.color.has(c)?'checked':''}> ${c}</label>`).join('')}</div><div class="side-group"><h3>Precio</h3><label class="check"><input type="checkbox" data-price="lt250" ${state.price.has('lt250')?'checked':''}> Menos de $250</label><label class="check"><input type="checkbox" data-price="250-349" ${state.price.has('250-349')?'checked':''}> $250 - $349</label><label class="check"><input type="checkbox" data-price="gte350" ${state.price.has('gte350')?'checked':''}> $350 o más</label></div></aside><div><div class="grid" id="grid">${arr.length?arr.map(productCard).join(''):'<div class="no-results">No encontré productos con esos filtros.</div>'}</div></div></div></section>`; $('#sortSelect').value=state.sort; bindDynamic();}
function renderDetail(sku){const p=PRODUCTS.find(x=>x.sku===sku)||PRODUCTS[0]; const main=p.images[0]; $('#app').innerHTML=`<section class="detail"><div class="gallery"><div class="thumbs">${p.images.map((src,i)=>`<button class="${i===0?'active':''}" data-thumb="${i}">${img(src,p.name)}</button>`).join('')}</div><div class="main-photo">${img(main,p.name)}</div></div><div class="detail-info"><div class="badge">${p.isNew?'Lo nuevo':p.isBestSeller?'Lo más vendido':'Disponible'}</div><h1>${p.name}</h1><p class="sub">${p.categoryLabel}${p.category.endsWith('-dama')?' '+p.audience:''}${p.color?' · '+p.color:''} · SKU ${p.sku}</p><div class="detail-price">${money(p.price)}</div><div class="select-row"><span>Selecciona presentación</span><span>Talla única</span></div><div class="sizes"><button class="size active">Unitalla</button><button class="size">Mayoreo</button><button class="size">Regalo</button></div><div class="detail-actions"><button class="primary" data-add="${p.sku}">Agregar a la bolsa de compra</button><button class="outline${state.favorites.has(p.sku)?' active':''}" data-favorite="${p.sku}">${state.favorites.has(p.sku)?'Favoritos ♥':'Favoritos ♡'}</button></div><div class="info-block"><h3>Descripción</h3><p>${p.longDescription}</p></div><div class="info-block"><h3>Detalles del producto</h3><ul class="meta-list">${p.material?`<li><strong>Material:</strong> ${p.material}</li>`:''}${p.measurements?`<li><strong>Medidas:</strong> ${p.measurements}</li>`:''}${p.weight?`<li><strong>Peso:</strong> ${p.weight} kg</li>`:''}<li><strong>Stock:</strong> ${p.stock} piezas</li>${p.satProductCode?`<li><strong>Código SAT:</strong> ${p.satProductCode}</li>`:''}<li><strong>Garantía:</strong> ${p.warrantyPeriod}</li></ul></div><div class="info-block"><h3>Garantía</h3><p>${p.warranty}</p></div></div></section>`; bindDynamic();}
function renderFavorites(){const arr=PRODUCTS.filter(p=>state.favorites.has(p.sku)); $('#app').innerHTML=`<section class="shop"><div class="breadcrumbs"><a href="#/">Inicio</a> / Favoritos</div><div class="shop-head"><div><h1>Favoritos (${arr.length})</h1></div></div><div class="grid" id="grid">${arr.length?arr.map(productCard).join(''):'<div class="no-results">Aún no tienes favoritos.</div>'}</div></section>`; bindDynamic();}
function renderSimple(page){const title=page==='mayoreo'?'Mayoreo':page==='contacto'?'Contacto':'Ayuda'; $('#app').innerHTML=`<section class="contact-page"><h1>${title}</h1><p>WhatsApp: <a class="textlink" href="https://wa.me/${WHATSAPP_NUMBER}">+52 55 4838 7767</a></p><p>Correo: <a class="textlink" href="mailto:${CONTACT_EMAIL}">${CONTACT_EMAIL}</a></p><form class="contact-form" onsubmit="event.preventDefault(); location.href='mailto:${CONTACT_EMAIL}?subject=Contacto Gioventrue&body='+encodeURIComponent(document.getElementById('msg').value)"><input placeholder="Nombre" aria-label="Nombre"><input placeholder="Correo" aria-label="Correo electrónico"><textarea id="msg" placeholder="Cuéntanos qué estás buscando" aria-label="Mensaje"></textarea><button class="primary">Enviar por correo</button></form></section>`;}
function renderAbout(){$('#app').innerHTML=`<section class="about-page"><div class="about-hero"><p class="about-eyebrow">Quiénes somos</p><h1>El detalle que transforma tu estilo</h1><p>35 años creando elegancia en cada detalle.</p></div><div class="about-section"><div class="about-essence"><p>En Gioventrue creemos que la elegancia comienza en los detalles. Cada accesorio es una oportunidad de transformar lo cotidiano en algo extraordinario, acompañando tu estilo con distinción y cuidado artesanal.</p></div></div><div class="about-section"><h2>Nuestra historia</h2><p>Gioventrue nació de la visión de Ana Karenina Lemus, quien hace 35 años fundó una empresa con un propósito claro: crear accesorios para el cabello que combinaran elegancia, calidad y pasión por los detalles. Desde sus inicios en Ciudad de México, Gioventrue ha crecido hasta convertirse en una marca de referencia en el mercado de accesorios, atendiendo las necesidades de bebés, niñas, damas y ahora para mascotas con una amplia variedad de diseños propios.</p></div><div class="about-section"><h2>Nuestras fortalezas</h2><div class="about-strengths"><div><h3>Experiencia &amp; Diseño</h3><p>Llevamos las marcas propias como MON CARAMEL, MAP, BABIESRUS, ya con años en el mercado. Diseño propio y amplio portafolio adaptado a cada cliente y segmento.</p></div><div><h3>Innovación &amp; Pasión</h3><p>Reinventamos tendencias con creatividad y dedicación, llevando confianza y cercanía a cada cliente que elige Gioventrue.</p></div></div></div><div class="about-section"><h2>Nuestras líneas</h2><p>Trabajamos con una amplia diversidad de materiales cuidadosamente seleccionados. Nuestras colecciones —básicas, tendencia y de temporada— están diseñadas para acompañar el estilo de cada mujer, niña y bebé, todos los días, sin importar la ocasión.</p><div class="about-lines"><div class="about-line-card"><h3>Bebés</h3><p>Accesorios suaves y delicados diseñados especialmente para las más pequeñas, con materiales seguros y confortables.</p></div><div class="about-line-card"><h3>Niñas</h3><p>Diseños coloridos y divertidos que acompañan cada aventura, llenos de creatividad y personalidad para las niñas.</p></div><div class="about-line-card"><h3>Damas</h3><p>Colecciones elegantes y versátiles para la mujer moderna, perfectas para cada ocasión y estilo de vida.</p></div><div class="about-line-card soon"><span class="about-badge-soon">Próximamente</span><h3>Mascotas</h3><p>¡Próximamente! Las mascotas también son parte de la familia. Una nueva línea de accesorios llena de amor y estilo.</p></div></div></div><div class="about-stats"><div><strong>+120,000</strong><span>piezas anuales</span></div><div><strong>99%</strong><span>entregas puntuales</span></div><div><strong>276</strong><span>modelos nuevos al año</span></div><div><strong>+100</strong><span>pedidos atendidos al año</span></div></div><div class="about-section"><div class="about-quality"><h2>Calidad y transparencia</h2><p>Gioventrue cuenta con una auditoría SMETA de 2 pilares. Este proceso respalda nuestro compromiso con la transparencia, la mejora continua y el abastecimiento responsable.</p></div></div><div class="about-cta"><h2>Conéctate con Gioventrue</h2><p>Te invitamos a descubrir un mundo donde cada detalle cuenta. Conéctate con Gioventrue y déjate inspirar por nuestra experiencia, elegancia, pasión y diseño.</p><a class="primary" href="https://wa.me/${WHATSAPP_NUMBER}">Escríbenos por WhatsApp</a></div></section>`;}
function bindDynamic(){$$('[data-add]').forEach(b=>b.onclick=e=>{e.preventDefault(); e.stopPropagation(); addToCart(b.dataset.add);}); $$('[data-favorite]').forEach(b=>b.onclick=e=>{e.preventDefault(); e.stopPropagation(); toggleFavorite(b.dataset.favorite);}); $$('.cat-card').forEach(b=>b.onclick=()=>{location.hash=b.dataset.audience?`#/productos?audience=${b.dataset.audience}`:`#/productos?cat=${b.dataset.cat}`;}); $$('input[name="cat"]').forEach(i=>i.onchange=()=>{renderProducts({cat:i.value,audience:state.audience});}); $$('[data-color]').forEach(i=>i.onchange=()=>{i.checked?state.color.add(i.dataset.color):state.color.delete(i.dataset.color); renderProducts();}); $$('[data-price]').forEach(i=>i.onchange=()=>{i.checked?state.price.add(i.dataset.price):state.price.delete(i.dataset.price); renderProducts();}); $('#sortSelect') && ($('#sortSelect').onchange=e=>{state.sort=e.target.value; renderProducts();}); $('#toggleFilters') && ($('#toggleFilters').onclick=()=>{const hidden=$('#sidebar').classList.toggle('sidebar-hidden'); $('#toggleFilters').textContent=hidden?'Mostrar filtros ⚙':'Ocultar filtros ⚙';}); $$('[data-thumb]').forEach(b=>b.onclick=()=>{const i=+b.dataset.thumb; const p=PRODUCTS.find(x=>x.sku===location.hash.split('/producto/')[1])||PRODUCTS[0]; $('.main-photo').innerHTML=img(p.images[i],p.name); $$('.thumbs button').forEach(x=>x.classList.remove('active')); b.classList.add('active');});}
function route(){const raw=location.hash||'#/'; const [path, query='']=raw.slice(2).split('?'); const params=Object.fromEntries(new URLSearchParams(query)); if(path.startsWith('producto/')) return renderDetail(path.split('/')[1]); if(path==='productos') return renderProducts(params); if(path==='favoritos') return renderFavorites(); if(path==='nosotros') return renderAbout(); if(['mayoreo','contacto','ayuda'].includes(path)) return renderSimple(path); renderHome();}
function addToCart(sku){const it=state.cart.find(x=>x.sku===sku); if(it) it.qty++; else state.cart.push({sku,qty:1}); saveCart(); renderCart(); openCart();}
function updateQty(sku,delta){const it=state.cart.find(x=>x.sku===sku); if(!it)return; it.qty+=delta; if(it.qty<=0) state.cart=state.cart.filter(x=>x.sku!==sku); saveCart(); renderCart();}
function renderCart(){const detail=state.cart.map(x=>({...PRODUCTS.find(p=>p.sku===x.sku), qty:x.qty})).filter(x=>x.sku); const total=detail.reduce((s,x)=>s+x.price*x.qty,0); $('#cartCount').textContent=detail.reduce((s,x)=>s+x.qty,0); $('#cartTotal').textContent=money(total); $('#cartEmpty').style.display=detail.length?'none':'grid'; $('#cartItems').innerHTML=detail.map(x=>`<div class="cart-item">${img(x.images[0],x.name)}<div><h3>${x.name}</h3><p>${x.color?x.color+' · ':''}${money(x.price)}</p><div class="qty"><button data-qty="-1" data-sku="${x.sku}">−</button><strong>${x.qty}</strong><button data-qty="1" data-sku="${x.sku}">+</button></div></div><button class="remove" data-remove="${x.sku}">×</button></div>`).join(''); $$('[data-qty]').forEach(b=>b.onclick=()=>updateQty(b.dataset.sku,+b.dataset.qty)); $$('[data-remove]').forEach(b=>b.onclick=()=>updateQty(b.dataset.remove,-999));}
function openCart(){$('#cart').classList.add('open'); document.body.classList.add('cart-open');}
function closeCart(){$('#cart').classList.remove('open'); document.body.classList.remove('cart-open');}
function checkout(){const detail=state.cart.map(x=>({...PRODUCTS.find(p=>p.sku===x.sku), qty:x.qty})).filter(x=>x.sku); if(!detail.length)return; const total=detail.reduce((s,x)=>s+x.price*x.qty,0); const lines=detail.map(x=>`• ${x.qty} x ${x.sku} - ${x.name} — ${money(x.price*x.qty)}`); const msg=encodeURIComponent(`Hola Gioventrue, quiero hacer este pedido:\n\n${lines.join('\n')}\n\nSubtotal estimado: ${money(total)}\n\n¿Me confirman disponibilidad, envío y forma de pago?`); window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${msg}`,'_blank');}
$('#favoritesBtn').onclick=()=>{location.hash='#/favoritos';}; $('#openCart').onclick=openCart; $$('[data-close-cart]').forEach(x=>x.onclick=closeCart); $('#checkoutBtn').onclick=checkout; $('#clearCart').onclick=()=>{state.cart=[];saveCart();renderCart();}; $('#globalSearch').onkeydown=e=>{if(e.key==='Enter'){state.query=e.target.value; location.hash=`#/productos?q=${encodeURIComponent(state.query)}`;}}; $('#mobileMenu').onclick=()=>$('#navLinks').classList.toggle('open'); window.addEventListener('hashchange',()=>{$('#navLinks').classList.remove('open'); route();}); renderCart(); route();
